""" list of first N prime numbers

    Args:
        N (int): number

    Returns:
        list: N prime numbers
    """
def N_primes(N: int) -> object {
    try {
        nums = [True] * (N * 100);
    } except Exception as e {
        nums = [True] * (N * 10);
    }
    count = 0;
    x = 1;
    primes = [];
    while (count < N) {
        x += 1;
        if nums[x] {
            primes.append(x);
            count += 1;
            for i in range(x, len(nums), x) {
                nums[i] = False;
            }
        }
    }
    return primes;
}
